    template_cells = set(range(start, start + len(colors)))
    # Marker color is the most frequent non-background color outside the pattern.
    counts = Counter(
        v for r, row in enumerate(grid) for c, v in enumerate(row)
        if v != bg and not (r == tr and c in template_cells)
